<?php require __DIR__.'/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}check_csrf();if(!ready()){http_response_code(503);exit('Chưa cài đặt.');}$type=$_POST['type']??'';$section=$type==='wish'?'wishes':'rsvp';try{if(trim((string)($_POST['website']??''))!=='')throw new Exception('Yêu cầu không hợp lệ.');rate_limit_submission($type==='wish'?'wish':'rsvp',20);$name=trim((string)($_POST['name']??''));if($name===''||text_length($name)>150)throw new Exception('Tên không hợp lệ.');if($type==='wish'){$message=trim((string)($_POST['message']??''));if($message===''||text_length($message)>1000)throw new Exception('Lời chúc không hợp lệ.');$q=db()->prepare('INSERT INTO wishes(name,message) VALUES (?,?)');$q->execute([$name,$message]);$_SESSION['flash']='Cảm ơn bạn! Lời chúc đang chờ duyệt.';}elseif($type==='rsvp'){$a=$_POST['attendance']??'';$n=filter_var($_POST['guests']??0,FILTER_VALIDATE_INT);$event=(string)($_POST['event_name']??'');$note=trim((string)($_POST['note']??''));if(!in_array($a,['yes','no'],true)||($a==='yes'&&($n===false||$n<1||$n>10))||!in_array($event,array_column(content()['events'],'name'),true)||text_length($note)>1000)throw new Exception('Thông tin xác nhận không hợp lệ.');$q=db()->prepare('INSERT INTO responses(name,attendance,guests,event_name,note) VALUES (?,?,?,?,?)');$q->execute([$name,$a,$a==='yes'?$n:0,$event,$note]);$_SESSION['flash']='Cảm ơn bạn đã xác nhận!';}else throw new Exception('Yêu cầu không hợp lệ.');}catch(Throwable $x){$_SESSION['flash']=$x instanceof PDOException?'Không lưu được dữ liệu.':$x->getMessage();}redirect('index.php#'.$section);
